xql_query:
// ============================================================
// Rule: CTX_Critical Endpoints Disconnected
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_Critical Endpoints Disconnected.
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================

// Configuração inicial: define que as comparações diferenciam maiúsculas/minúsculas  
config case_sensitive = true  

// Fonte de dados: dataset principal de inventário de endpoints  
// O dataset 'endpoints' contém informações de status, último check-in e nome do host  
| dataset = endpoints  

// Seleção dos campos relevantes para análise de conectividade dos agentes  
| fields 
    endpoint_name,       // Nome do endpoint (hostname reportado pelo agente XDR)  
    last_seen,           // Último momento em que o agente enviou telemetria  
    endpoint_status      // Status atual do agente (Connected / Disconnected / Uninstalled)  

// Filtro para retornar apenas endpoints com status "DISCONNECTED"  
| filter endpoint_status = "DISCONNECTED"  

// 🔹 Join com dataset de endpoints críticos  
// Retorna apenas endpoints cujo hostname esteja listado no dataset 'endpoints_critical'  
| join conflict_strategy = both type = inner (
    dataset = endpoints_critical
    | fields hostname as hostname_critico
) as CR CR.hostname_critico = endpoint_name  

// 🔹 Join adicional com dataset de endpoints SI (sensíveis)  
// Retorna também endpoints que constem no dataset 'endpoints_si'  
| join conflict_strategy = both type = inner (
    dataset = endpoints_si
    | fields hostname as hostname_si
) as SI SI.hostname_si = endpoint_name  

// 🔹 Exibe os campos finais relevantes para monitoramento  
| fields 
    endpoint_name as Hostname,     // Nome do host  
    endpoint_status as Status,     // Status atual do agente  
    last_seen as Ultima_Conexao    // Último check-in do agente
